def assign_markets(apps, schema_editor):
    """
    Give every existing price a market:
    - a source that names a market of the same municipality (e.g. "Carbon
      Market") uses that market;
    - other Cebu City prices go to Pasil Fish Market (the study's market),
      which is created when missing;
    - a municipality with exactly one market uses it; otherwise none.
    """
    Municipality = apps.get_model("api", "Municipality")
    Market = apps.get_model("api", "Market")
    PriceRecord = apps.get_model("api", "PriceRecord")

    cebu = Municipality.objects.filter(name__iexact="Cebu City").first()
    if cebu is not None:
        pasil = Market.objects.filter(municipality=cebu, name__icontains="pasil").first()
        if pasil is None:
            Market.objects.create(municipality=cebu, name="Pasil Fish Market", is_active=True)

    for place in Municipality.objects.all():
        markets = list(Market.objects.filter(municipality=place))
        if not markets:
            continue
        if place.name.lower() == "cebu city":
            default = next((m for m in markets if "pasil" in m.name.lower()), None)
        else:
            default = markets[0] if len(markets) == 1 else None
        records = PriceRecord.objects.filter(municipality=place, market__isnull=True)
        for market in markets:
            key = market.name.lower().replace("fish market", "").replace("public market", "").replace("market", "").strip()
            if key:
                records.filter(source__icontains=key).update(market=market)
        if default is not None:
            PriceRecord.objects.filter(municipality=place, market__isnull=True).update(market=default)


